// ─── Aura Music Background Download Service Worker ────────────────────────
// Handles:  1. Background Fetch (download continues after tab/browser close)
//           2. Background audio keep-alive pings
//           3. Static asset caching
//           4. Lock screen / notification click handling

// ── Utility: importScripts Workbox if present (injected by next-pwa) ──
// The actual SW file used in production is generated by next-pwa/workbox.
// This file is loaded as an ADDITIONAL sw via next-pwa's `customWorkerSrc`.
// So we only need to handle the extra features here.

// ─────────────────────────────────────────────────────────────────────────────
//  BACKGROUND FETCH HANDLERS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Called when a Background Fetch registration is created from the page.
 * The page sends: { type: 'BG_FETCH_START', fetchId, urls, metadata }
 */
self.addEventListener('backgroundfetchsuccess', (event) => {
  const bgFetch = event.registration;

  event.waitUntil(async function () {
    // Open a cache named after this fetch
    const cache = await caches.open('aura-bg-downloads');
    const records = await bgFetch.matchAll();

    const meta = JSON.parse(bgFetch.id.startsWith('{')
      ? bgFetch.id
      : '{}');

    // Store each fetched response into Cache Storage
    await Promise.all(
      records.map(async (record) => {
        const response = await record.responseReady;
        await cache.put(record.request, response);
      })
    );

    // Notify all open clients (tabs) that download is done
    const clients = await self.clients.matchAll({ includeUncontrolled: true });
    for (const client of clients) {
      client.postMessage({
        type: 'BG_FETCH_DONE',
        fetchId: bgFetch.id,
        title: meta.title || 'أغنية',
        success: true,
      });
    }

    // Show a completion notification
    await self.registration.showNotification('Aura Music — تم التحميل ✅', {
      body: `"${meta.title || 'الأغنية'}" جاهزة للتشغيل بدون إنترنت`,
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      tag: `dl-done-${bgFetch.id}`,
      data: { url: '/' },
    });
  }());
});

self.addEventListener('backgroundfetchfail', (event) => {
  event.waitUntil(async function () {
    const clients = await self.clients.matchAll({ includeUncontrolled: true });
    for (const client of clients) {
      client.postMessage({ type: 'BG_FETCH_FAIL', fetchId: event.registration.id });
    }
  }());
});

self.addEventListener('backgroundfetchabort', (event) => {
  event.waitUntil(async function () {
    const clients = await self.clients.matchAll({ includeUncontrolled: true });
    for (const client of clients) {
      client.postMessage({ type: 'BG_FETCH_ABORT', fetchId: event.registration.id });
    }
  }());
});

/** Progress updates while download is happening */
self.addEventListener('backgroundfetchprogress', (event) => {
  event.waitUntil(async function () {
    const reg = event.registration;
    const clients = await self.clients.matchAll({ includeUncontrolled: true });
    for (const client of clients) {
      client.postMessage({
        type: 'BG_FETCH_PROGRESS',
        fetchId: reg.id,
        downloaded: reg.downloaded,
        downloadTotal: reg.downloadTotal,
        result: reg.result,
      });
    }
  }());
});

// ─────────────────────────────────────────────────────────────────────────────
//  MESSAGES FROM THE PAGE
// ─────────────────────────────────────────────────────────────────────────────
self.addEventListener('message', (event) => {
  if (!event.data) return;

  if (event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }

  if (event.data.type === 'AUDIO_PLAYING') {
    // Keep SW alive while audio is streaming
    event.waitUntil(Promise.resolve());
  }

  // Page asks SW to start a Background Fetch download
  if (event.data.type === 'BG_FETCH_START') {
    const { fetchId, url, title, artist, songId } = event.data;
    event.waitUntil(
      self.registration.backgroundFetch.fetch(
        fetchId,
        [url],
        {
          title: `Aura — ${title}`,
          icons: [{ src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' }],
          downloadTotal: 0, // unknown
        }
      ).then((reg) => {
        // Tell client: fetch has started
        if (event.source) {
          event.source.postMessage({ type: 'BG_FETCH_REGISTERED', fetchId, regId: reg.id });
        }
      }).catch((err) => {
        // Background Fetch not supported — fall back silently
        console.warn('[SW] BackgroundFetch not supported:', err.message);
        if (event.source) {
          event.source.postMessage({ type: 'BG_FETCH_UNSUPPORTED', fetchId });
        }
      })
    );
  }
});

// ─────────────────────────────────────────────────────────────────────────────
//  NOTIFICATION CLICK
// ─────────────────────────────────────────────────────────────────────────────
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data?.url || '/';
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) return client.focus();
      }
      return self.clients.openWindow(targetUrl);
    })
  );
});
